    descriptionAdvanced: {
      de: "Der Royal Botanic Garden von Jordanien befindet sich in Tell Ar-Rumman, etwa 25 Kilometer nördlich von Amman, und überblickt den King-Talal-Damm. Das 2005 auf Initiative von Prinzessin Basma bint Ali gegründete Projekt widmet sich der Erhaltung der biologischen Vielfalt und der einheimischen Flora des Landes. Das Gelände umfasst etwa 170 Hektar und beherbergt über 600 Pflanzenarten, von denen viele im Nahen Osten endemisch sind. Der Garten fungiert als lebendes Museum und Forschungszentrum, das sich auf nachhaltige Landbewirtschaftung und den Schutz bedrohter Ökosysteme konzentriert. Besucher können verschiedene thematische Zonen erkunden, die die unterschiedlichen klimatischen Regionen Jordaniens widerspiegeln, von Pinienwäldern bis hin zu Trockenzonen. Neben der wissenschaftlichen Arbeit dient der Garten auch der Umweltbildung und bietet Programme an, die das Bewusstsein für die Bedeutung des Naturschutzes in einer wasserarmen Region wie Jordanien schärfen.",
      hu: "Jordánia Királyi Botanikus Kertje Tell Ar-Rumman területén található, mintegy 25 kilométerre északra Ammantól, kilátással a King Talal-gátra. A projektet 2005-ben alapították Basma bint Ali hercegnő kezdeményezésére, azzal a céllal, hogy megőrizzék az ország biológiai sokféleségét és őshonos növényvilágát. A kert területe körülbelül 170 hektár, és több mint 600 növényfajnak ad otthont, amelyek közül sok endemikus a Közel-Keleten. Az intézmény élő múzeumként és kutatóközpontként is működik, fókuszában a fenntartható földhasználat és a veszélyeztetett ökoszisztémák védelme áll. A látogatók különböző tematikus zónákat fedezhetnek fel, amelyek Jordánia eltérő éghajlati régióit reprezentálják, a fenyőerdőktől a sivatagi területekig. A tudományos munka mellett a kert környezeti neveléssel is foglalkozik, olyan programokat kínálva, amelyek felhívják a figyelmet a természetvédelem fontosságára a vízhiánnyal küzdő régióban.",
      ro: "Grădina Botanică Regală a Iordaniei este situată în Tell Ar-Rumman, la aproximativ 25 de kilometri nord de Amman, oferind o vedere panoramică asupra barajului King Talal. Fondat în 2005 la inițiativa Prințesei Basma bint Ali, acest proiect este dedicat conservării biodiversității și florei native a țării. Situl se întinde pe aproximativ 170 de hectare și găzduiește peste 600 de specii de plante, dintre care multe sunt endemice în Orientul Mijlociu. Grădina funcționează ca un muzeu viu și centru de cercetare, concentrându-se pe managementul durabil al terenurilor și protejarea ecosistemelor amenințate. Vizitatorii pot explora diverse zone tematice care reflectă regiunile climatice distincte ale Iordaniei, de la păduri de pini la zone aride. Pe lângă activitatea științifică, grădina servește și educației ecologice, oferind programe care sporesc gradul de conștientizare privind importanța conservării naturii într-o regiune cu resurse limitate de apă.",
      en: "The Royal Botanic Garden of Jordan is located in Tell Ar-Rumman, approximately 25 kilometers north of Amman, overlooking the King Talal Dam. Established in 2005 under the initiative of Princess Basma bint Ali, the project is dedicated to conserving the nation's biodiversity and native flora. The site encompasses about 170 hectares and is home to over 600 plant species, many of which are endemic to the Middle East. The garden operates as a living museum and research center, focusing on sustainable land management and the protection of threatened ecosystems. Visitors can explore various thematic zones that reflect Jordan's diverse climatic regions, ranging from pine forests to arid zones. Beyond its scientific work, the garden also serves as a hub for environmental education, offering programs that raise awareness about the importance of nature conservation in a water-scarce region like Jordan.",
      es: "El Jardín Botánico Real de Jordania se encuentra cerca de Amán, en la región de Tall al-Ma'daba. Se extiende sobre 1.200 hectáreas y muestra especies de plantas nativas que crecen en diversos hábitats. El jardín sirve para la conservación de la biodiversidad, la investigación y la educación ambiental. Alberga el Herbario Nacional y una base de datos con más de 800 especies de plantas. Las atracciones incluyen un sistema de lagos, senderos y una pasarela sobre las copas de los árboles. El jardín es parte de un proyecto de conservación más amplio. Fue inaugurado oficialmente en 2013. El jardín también ofrece cursos sobre agricultura sostenible. Unas 100.000 personas visitan el jardín anualmente.",
      pt: "O Jardim Botânico Real da Jordânia está localizado perto de Amã, na região de Tall al-Ma'daba. Estende-se por 1.200 hectares e exibe espécies de plantas nativas que crescem em diversos habitats. O jardim serve para a conservação da biodiversidade, investigação e educação ambiental. Abriga o Herbário Nacional e uma base de dados com mais de 800 espécies de plantas. As atrações incluem um sistema de lagos, trilhos para caminhadas e um passadiço sobre as copas das árvores. O jardim faz parte de um projeto de conservação maior. Foi inaugurado oficialmente em 2013. O jardim também oferece cursos sobre agricultura sustentável. Cerca de 100.000 pessoas visitam o jardim anualmente.",
      fr: "Le jardin botanique royal de Jordanie est situé près d'Amman, dans la région de Tall al-Ma'daba. Il s'étend sur 1 200 hectares et présente des espèces végétales indigènes poussant dans divers habitats. Le jardin se consacre à la préservation de la biodiversité, à la recherche et à l'éducation environnementale. Il abrite l'Herbier national et une base de données de plus de 800 espèces végétales. Les attractions incluent un système de lacs, des sentiers de randonnée et une passerelle à la cime des arbres. Le jardin fait partie d'un projet de conservation plus vaste. Il a été officiellement inauguré en 2013. Le jardin propose également des cours sur l'agriculture durable. Environ 100 000 personnes visitent le jardin chaque année.",
    },
