    name: { de: "Amman Nationalpark", hu: "Ammán Nemzeti Park", ro: "Parcul Național Amman", en: "Amman National Park"},
    image: "/poi-images/amman-national-park-life-v2.webp",
    description: { de: "Dieser weitläufige Park im Süden von Amman ist ein beliebtes Ziel für Picknicks und Familienausflüge. Seine dichten Pinienwälder bieten eine erfrischende grüne Flucht vor der Hitze der Stadt.", hu: "Ez a hatalmas park Ammán déli részén a családok és a piknikezők egyik legkedveltebb célpontja. Sűrű fenyőerdői frissítő, zöld menedéket nyújtanak a városi hőség elől.", ro: "Acest parc întins din sudul Ammanului este o destinație populară pentru picnicuri și ieșiri în familie. Pădurile sale dense de pini oferă o evadare verde și răcoroasă din căldura orașului.", en: "This expansive park in southern Amman is a popular destination for picnics and family outings. Its dense pine forests provide a refreshing green escape from the city heat." , es: "Este extenso parque al sur de Amán es un destino popular para picnics y excursiones familiares. Sus densos bosques de pinos ofrecen un refrescante escape verde frente al calor de la ciudad.", pt: "Este amplo parque ao sul de Amã é um destino popular para piqueniques e passeios em família. Seus densos pinhais oferecem um refúgio verde refrescante contra o calor da cidade.", fr: "Ce vaste parc au sud d'Amman est une destination prisée pour les pique-niques et les sorties en famille. Ses denses forêts de pins offrent une escapade verdoyante et rafraîchissante face à la chaleur de la ville."},
