      es: ["Lugar de picnic popular para los lugareños.", "Cuenta con densos bosques de pinos.", "Ofrece áreas de juegos y de barbacoa.", "Un oasis verde cerca de la capital."],
      pt: ["Local de piquenique popular para os moradores locais.", "Possui florestas de pinheiros densas.", "Oferece parques infantis e áreas de churrasco.", "Um oásis verde perto da capital."],
