      pt: ["O centro foi inaugurado em 2006.", "Abriga a sede da RSCN.", "A área de exposição é de 500 metros quadrados.", "Cerca de 50.000 pessoas visitam o centro anualmente.", "O restaurante utiliza ingredientes de produção local.", "O edifício é construído com pedra local."],
